export function statusGroupOf(status: TransactionStatus): StatusGroup {
  return tokens.transactionStatusGroup[status] as StatusGroup;
}

export function trustTierOf(score: number): TrustTier {
  const s = Math.max(0, Math.min(100, Math.round(score)));
  for (const [tier, r] of Object.entries(tokens.trustTier) as [TrustTier, { min: number; max: number }][]) {
    if (s >= r.min && s <= r.max) return tier;
  }
  return 'low';
}

export function statusTone(status: TransactionStatus, theme: ThemeName = 'light') {
  return tokens.color.status[theme][statusGroupOf(status)];
}

export default tokens;
